import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.CFuv5BrO.js";const b=JSON.parse('{"title":"执行器与路由","description":"Hearth 为什么使用多种专长执行器，以及如何按能力、风险和成本选择执行方式。","frontmatter":{"title":"执行器与路由","description":"Hearth 为什么使用多种专长执行器，以及如何按能力、风险和成本选择执行方式。","outline":false},"headers":[],"relativePath":"design/executors.md","filePath":"design/executors.md","lastUpdated":1794373393000}'),a={name:"design/executors.md"};function c(s,t,i,h,n,p){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="执行器与路由" tabindex="-1">执行器与路由 <a class="header-anchor" href="#执行器与路由" aria-label="Permalink to &quot;执行器与路由&quot;">​</a></h1><p class="lead">Hearth 不把所有工作交给一个万能模型。通用推理、代码执行、连接器、浏览器、桌面操作、文档处理和人的判断各有边界，系统根据任务需要选择最合适的一种或几种能力。</p><h2 id="设计目标" tabindex="-1">设计目标 <a class="header-anchor" href="#设计目标" aria-label="Permalink to &quot;设计目标&quot;">​</a></h2><p>执行器要能把一个工作单元真正做完，并返回结构清楚的结果：产物在哪里、依据是什么、哪些步骤成功、哪些步骤失败、是否产生了外部副作用、下一步应该验证还是转人工。执行器还要支持取消、超时、恢复和预算限制，不能一旦启动就无法收回。</p><p>不同任务需要不同能力。代码、长文档和复杂研究适合能力更强、工作区更完整的执行器；邮件、日历和云盘优先使用有明确接口的连接器；没有接口的网站使用浏览器；没有网页入口的软件使用桌面操作；解析、转换、表格和对账优先使用确定性的文档数据处理；需要承担责任的价值判断交给用户。</p><p>路由的目标不是“永远先用某个工具”，而是在硬约束下选择最可能成功、风险可控、成本合理的路径。权限、数据驻留、可逆性和安全等级是硬约束，成功率、延迟和费用是在满足硬约束之后的优化目标。</p><p>执行器之间要能协作，但不共享隐式状态。一个任务可以由浏览器取回资料、通用模型归纳、文档执行器生成表格、代码执行器完成复杂处理，最后由用户审批并由连接器发送。每一步都应说明输入、输出和负责范围，避免一个执行器把自己的猜测当成另一个执行器的事实。</p><h2 id="设计取舍" tabindex="-1">设计取舍 <a class="header-anchor" href="#设计取舍" aria-label="Permalink to &quot;设计取舍&quot;">​</a></h2><p>Hearth 选择多个专长执行器并列，而不是一个无限扩展能力的超级代理。这样可以把权限、隔离、预算和失败恢复放在清楚的边界里，也可以根据真实数据替换表现不好的路径。</p><table tabindex="0"><thead><tr><th>执行器</th><th>更适合</th><th>不适合</th></tr></thead><tbody><tr><td>Hearth 原生</td><td>通用执行内核：多文件编辑、资料读取、网页研究、办公产物、技能复用、有界委派、本地 MCP 和项目 Worktree</td><td>需要 LSP、格式化器或完整 IDE 语义时</td></tr><tr><td>Codex</td><td>多文件、代码、长文档、复杂研究和深度写作</td><td>需要长期在线监听、低成本高频响应</td></tr><tr><td>连接器</td><td>邮件、日历、云盘、即时消息、工单等有接口的系统</td><td>没有接口、需要操作图形界面的软件</td></tr><tr><td>浏览器</td><td>网页研究、登录态、表单和软件即服务</td><td>高敏感凭据直接暴露、不可审计的批量操作</td></tr><tr><td>桌面操作</td><td>没有开放接口的本地软件和跨应用流程</td><td>需要绝对确定性和高吞吐的重复任务</td></tr><tr><td>文档与数据</td><td>解析、转换、表格、对账和确定性处理</td><td>开放式判断、复杂跨系统协作</td></tr><tr><td>人工</td><td>价值判断、责任承担、异常接管和审批</td><td>高频、低价值、已经可以自动验证的工作</td></tr></tbody></table><p>路由顺序不是固定等级。能规则、脚本或官方接口完成的工作不调用模型；需要外部数据时先找连接器，没有连接器再考虑浏览器或桌面；确定性文档处理不交给生成模型；长链路和复杂产物再选择高能力执行器。同一任务可以在中途换执行器，但换执行器必须保留输入、预算、权限和当前证据。</p><p>当前注册表包含七个执行器，按接入深度分成一等执行器和外部执行器。它们共用启动解析、健康检测、托管安装、模型绑定、上下文采集和设置界面，但适配器实现与能力上限不同。</p><table tabindex="0"><thead><tr><th>执行器</th><th>层级</th><th>接入方式</th><th>能力上限与边界</th></tr></thead><tbody><tr><td><code>deepseek-harness</code></td><td>一等</td><td>官方 <code>@deepseek-ai/dsh-sdk-client</code> SDK/JSON-RPC</td><td>完整 DeepSeek Harness 运行时：原生工具、代码、仓库、测试、会话恢复和完整事件流；需要有效模型绑定</td></tr><tr><td><code>codex</code></td><td>一等</td><td>本机 Codex Profile 或统一模型绑定生成的 <code>config.toml</code></td><td>多文件代码、仓库、测试、构建和 GitHub 工作区；模型协议固定为 OpenAI Responses</td></tr><tr><td><code>native</code></td><td>一等</td><td>Hearth 自有通用执行内核（模型协议、工具、压缩、委派、Worktree、本地 MCP）</td><td>通用任务、多文件编辑、研究办公、技能、隔离 Worktree 和本地 stdio MCP；支持四种模型协议</td></tr><tr><td><code>hermes</code></td><td>外部</td><td><code>PATH</code> 中的 <code>hermes</code> 命令或自定义命令</td><td>通用代理、多步工具调用和自动化流程；支持 CLI 会话恢复</td></tr><tr><td><code>qoder</code></td><td>外部</td><td><code>@qoder-ai/qoder-agent-sdk</code>，复用本机 qodercli 登录或 PAT</td><td>编码、工作区和会话续跑</td></tr><tr><td><code>workbuddy</code></td><td>外部</td><td><code>@tencent-ai/codebuddy-code</code>，复用本机登录</td><td>编码、工作区和会话续跑</td></tr><tr><td><code>kimi</code></td><td>外部</td><td><code>@moonshot-ai/kimi-code</code> 的 stream-json 模式</td><td>编码、工作区和非交互批量执行</td></tr></tbody></table><p>一等执行器不是“永远更强”，而是接入更深、可控面更完整。复杂代码和仓库任务优先 <code>codex</code> 或 <code>deepseek-harness</code>；通用任务、网页、文档、技能和本地项目 Worktree 优先 <code>native</code>；外部执行器适合已经拥有对应 CLI、登录或团队习惯的场景。用户显式选择本地项目后，任务默认由 native 在隔离 Worktree 中执行；GitHub 工程任务仍默认 Codex。项目不再集成 ZCode。</p><p>原生执行器由 Hearth 自己实现通用执行内核，包含预算、检查点、等待用户补充、上下文压缩、按需技能、有界委派、本地 MCP 和恢复，不是一段转发提示词。DeepSeek Harness 使用官方 SDK，不是解析命令行文本。Codex 使用专用适配器并遵守 Responses 协议。执行器不会因为一次失败而静默替换身份，实际执行器会写入运行记录和产物清单。</p><h2 id="统一模型绑定" tabindex="-1">统一模型绑定 <a class="header-anchor" href="#统一模型绑定" aria-label="Permalink to &quot;统一模型绑定&quot;">​</a></h2><p>每个执行器在设置中绑定一个模型档案，而不是各写一份私有配置。模型档案保存 Provider、协议、服务地址、模型名和加密后的 API Key；执行器绑定可以选择协议或模型覆盖，但服务端会强制校验兼容性：</p><table tabindex="0"><thead><tr><th>执行器</th><th>允许协议</th></tr></thead><tbody><tr><td><code>native</code></td><td>OpenAI Chat、OpenAI Responses、Anthropic Messages、Gemini</td></tr><tr><td><code>codex</code></td><td>仅 OpenAI Responses</td></tr><tr><td><code>deepseek-harness</code></td><td>OpenAI Chat、OpenAI Responses、Anthropic Messages</td></tr><tr><td><code>hermes</code>、<code>qoder</code>、<code>workbuddy</code>、<code>kimi</code></td><td>OpenAI Chat、OpenAI Responses、Anthropic Messages</td></tr></tbody></table><p>Hearth 当前聊天模型是 <code>app_settings.model.chatProfileId</code>，用于聊天、原生执行器和失败原因诊断。外部执行器只有绑定有效时才使用自己的档案。Codex 的绑定会生成 <code>.hearth/executors/codex/config.toml</code> 并通过环境变量注入密钥；DeepSeek Harness 会把协议映射写进自己的 Provider 配置。本地模型不进入统一模型管理，避免把本机端口误当成云端服务。完整存储边界见<a href="/hearth-os/design/storage.html">存储与上下文架构</a>。</p><h2 id="失败诊断与接管" tabindex="-1">失败诊断与接管 <a class="header-anchor" href="#失败诊断与接管" aria-label="Permalink to &quot;失败诊断与接管&quot;">​</a></h2><p>失败处理先分类，再决定是否换执行器。权限、缺少输入、预算耗尽、外部动作状态不确定和中断属于非执行器故障；运行环境故障、能力不足、交付契约不满足和临时故障才进入接管判断。</p><ol><li>先用确定性规则分类。临时故障允许同一执行器重试一次。</li><li>涉及执行器故障时，用 <strong>Hearth 当前聊天模型</strong> 读取任务、失败信息、运行记录和最近上下文，给出原因、置信度、建议动作和不要重复的尝试。诊断不使用失败执行器的模型，避免同一个故障模型替自己辩护。</li><li>处于完全权限、上下文模式开启且风险为低时，自动切换到下一个合格执行器并继续原任务。</li><li>处于必要审批模式时，只询问“是否切换到 <code>目标执行器</code> 继续？”，确认后才复用原任务、剩余预算和上下文水位启动新运行。</li><li>不是执行器问题时直接向用户说明错误原因，不切换执行器。</li></ol><p>回退顺序为 <code>deepseek-harness → codex → native → hermes → qoder → workbuddy → kimi</code>。已尝试的执行器不会重复选择；默认最多接管两次。接管包包含诊断摘要、已完成事项、失败事项、产物、未解决问题、剩余预算和 <code>context_watermark_seq</code>，目标执行器从同一上下文水位继续。每次交接都写入 <code>handoffs</code> 并生成 <code>HANDOFF.md</code>；宿主在切换前校验目标、验收、权限、游标和产物哈希，验证失败会阻止执行器切换，<code>HANDOFF.md</code> 作为真实 artifact 持久化并记录 <code>artifactRef</code>。运行记录保留来源执行器和目标执行器，旧 generation 的工具写入会被拒绝，但失败运行自己的诊断和决策证据仍会保留。</p><h2 id="统一上下文" tabindex="-1">统一上下文 <a class="header-anchor" href="#统一上下文" aria-label="Permalink to &quot;统一上下文&quot;">​</a></h2><p>所有执行器都适配 Hearth 的任务级上下文，而不是各用一份聊天历史。原生运行时、Codex、DeepSeek Harness 和外部 CLI 的助手消息、工具调用、工具结果、检查点和通知，都会通过统一回调写入 <code>context_items</code>。<code>executor_event_id</code> 保证一次运行内重复事件不会重复入库；超长正文落到 <code>.hearth/context/blobs/</code>；任务摘要写入 <code>task_context_state</code>；启动和接管时按预算生成上下文投影。</p><p>CLI 自己的 <code>sessionId</code> 只用于优化续跑，不是事实源。即使会话恢复失败，Hearth 仍可从共享上下文重建任务投影。上下文删除、保留期和接管次数由设置中的“上下文”分区统一管理。完整生命周期见<a href="/hearth-os/design/storage.html">存储与上下文架构</a>。</p><h2 id="设置页边界" tabindex="-1">设置页边界 <a class="header-anchor" href="#设置页边界" aria-label="Permalink to &quot;设置页边界&quot;">​</a></h2><p>设置页按九个分区组织：</p><table tabindex="0"><thead><tr><th>分区</th><th>负责什么</th></tr></thead><tbody><tr><td>执行器</td><td>默认执行器、安装与健康、命令或脚本路径、并发数、每个执行器的模型绑定</td></tr><tr><td>模型</td><td>模型档案增删改、当前聊天模型、拉取模型、连接测试和掩码 Key</td></tr><tr><td>项目</td><td>本地 Git 项目注册、默认分支和仓库状态</td></tr><tr><td>扩展</td><td>本地 stdio MCP 服务器与 Tavily/SearXNG 网页搜索设置</td></tr><tr><td>主动</td><td>提醒预算、安静时段和触发器</td></tr><tr><td>记忆与技能</td><td>自动运行状态和技能治理</td></tr><tr><td>连接</td><td>飞书入口和外部账户</td></tr><tr><td>上下文</td><td>模式、预算、保留期、接管次数、指标和清理</td></tr><tr><td>数据</td><td>SQLite 路径、执行器目录、上下文 blob、迁移记录和备份</td></tr></tbody></table><p>全局“默认执行器”只作为新对话的初始值；对话输入框的选择器可以覆盖它。选择不可用、缺少任务所需能力或没有有效模型绑定时，路由先回到任务原始匹配的执行器，再按注册表顺序寻找可用项。</p><h2 id="接入一个新执行器" tabindex="-1">接入一个新执行器 <a class="header-anchor" href="#接入一个新执行器" aria-label="Permalink to &quot;接入一个新执行器&quot;">​</a></h2><p>新增执行器不使用分叉的特殊路径，而是沿同一条注册表链路完成：</p><ol><li>在 <code>packages/core/src/types.ts</code> 的 <code>EXECUTOR_IDS</code> 中增加稳定 ID；只有确实具备完整适配、诊断和验证能力时才加入 <code>FIRST_CLASS_EXECUTOR_IDS</code>。</li><li>在 <code>apps/server/src/executors.ts</code> 增加名称、说明、能力、层级、Provider 和续跑支持；如果它能读取本地 GitHub 工作区，把它加入对应能力列表。</li><li>在 <code>apps/server/src/executor-runtime.ts</code> 增加启动解析：优先使用用户配置路径，其次托管安装，再检测全局安装和 <code>PATH</code>；同时提供版本探测和健康状态。</li><li>在 <code>apps/server/src/executor-install.ts</code> 增加固定版本的包规格。无法托管安装的桌面应用应明确返回不支持，并给出检测或手工路径提示。</li><li>在 <code>apps/server/src/model-registry.ts</code> 的 <code>EXECUTOR_MODEL_PROTOCOLS</code> 声明协议边界，并验证绑定能生成对应 CLI 或 SDK 的配置。</li><li>在 <code>apps/server/src/external-executor.ts</code> 或专用包中增加参数构造和流式解析；在 <code>apps/server/src/executor-adapter.ts</code> 注册适配器，并实现上下文回调。</li><li>补充测试：launch 解析、健康探测、安装任务、参数与事件解析、模型绑定协议校验、偏好路由、失败分类、接管和上下文采集。前端设置页和执行器选择器从 <code>/api/executors</code> 与 <code>/api/model-registry</code> 自动渲染。</li></ol><p>这条流程的约束是：执行器只能返回结果和证据，不能直接改任务状态；外部副作用仍由 Hearth 的审批和效果账本处理；凭据留在本机 CLI 或环境变量中，不写入任务上下文。</p><p>执行器的输出契约统一，但执行方式不统一。系统关心的是结果类型、证据、产物、失败分类和可恢复性，不关心某个执行器内部用了什么模型或界面。这样可以在不改变任务层的前提下替换模型、增加新工具或降级到人工。</p><p>路由结果要用真实数据更新。历史成功率、失败类型、人工接管率、延迟和成本都应该进入选择依据；一次演示成功不能证明某个执行器长期更好。高风险动作的权限和数据范围优先于速度与费用，不能用更高的成功率抵消越权风险。</p>',36)])])}const u=e(a,[["render",c]]);export{b as __pageData,u as default};
